#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// MetricsView's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/metrics_view.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// The heading painted above the metrics; it is also the accessible name.
template <typename Declaring>
struct MetricsViewTitleCapability {
    PropertyCell<std::string, MetricsViewTitleCapability<Declaring>> title{};

    static void assign(MetricsViewTitleCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.title), incoming);
        if (!capability.title.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.title));
    }
};

// The width of the accent bar at the leading edge, 1 to 32 (default 5). A value outside that range throws std::invalid_argument and changes nothing.
template <typename Declaring>
struct MetricsViewAccentWidthCapability {
    PropertyCell<double, MetricsViewAccentWidthCapability<Declaring>> accent_width{5.0};

    static void assign(MetricsViewAccentWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.accent_width), incoming);
        if (!capability.accent_width.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.accent_width));
    }
};

// Every MetricsView capability, in the order the declaring class takes them.
template <typename Declaring>
struct MetricsViewCapabilities : public MetricsViewTitleCapability<Declaring>,
                                 public MetricsViewAccentWidthCapability<Declaring> {};

} // namespace gui_forms
